import matplotlib.pyplot as plt
import numpy as np
from scipy.signal import find_peaks

fs = 125_000 #Hz

def find_and_plot_envelope_edge_peaks(envelope_edge):
    """Find all peaks in an envelope-edge signal and plot them as red dots."""
    envelope_edge = np.asarray(envelope_edge)

    peak_kwargs = {"distance": 5}
    peak_kwargs["prominence"] = 1000
    peak_kwargs["height"] = np.max(envelope_edge) * 0.71

    peak_indices, _ = find_peaks(envelope_edge, **peak_kwargs)
    plt.plot(peak_indices, -envelope_edge[peak_indices], "ro", label="Peaks")
    return peak_indices

def plot_idxs_lines(idxs, color="red", label=None):
    """Plot vertical lines at the specified indices."""
    for idx in idxs:
        plt.axvline(x=idx, color=color, linestyle="--", label=label)
        label = None  # Only label the first line to avoid duplicate legend entries

